<?php
/* ---------------------------------------------------------
   Human Coins — paquete autoinstalable
   Sube SOLO este archivo a la raiz del sitio y abrelo en el
   navegador. Escribe todos los archivos y luego te lleva al
   instalador. Cuando termines, borra este archivo.
--------------------------------------------------------- */

$ARCHIVOS = [
    'index.php' => '',
    'panel.php' => '',
    'estadisticas.php' => '',
    'salir.php' => '',
    'config.php' => '',
    'instalar.php' => '',
    'estilo.css' => '',
    'sw.js' => '',
    'manifest.json' => '',
    'moneda.webp' => '',
    'iconos/icono-192.jpg' => '',
    'iconos/icono-512.jpg' => '',
    'iconos/icono-maskable-512.jpg' => '',
    'iconos/apple-touch-icon.jpg' => '',
];

$errores = [];
$escritos = [];

foreach ($ARCHIVOS as $ruta => $b64) {
    $destino = __DIR__ . '/' . $ruta;
    $carpeta = dirname($destino);

    if (!is_dir($carpeta) && !@mkdir($carpeta, 0755, true)) {
        $errores[] = 'No pude crear la carpeta ' . dirname($ruta);
        continue;
    }

    $datos = base64_decode($b64, true);
    if ($datos === false) {
        $errores[] = 'Datos corruptos en ' . $ruta;
        continue;
    }

    if (@file_put_contents($destino, $datos) === false) {
        $errores[] = 'No pude escribir ' . $ruta;
        continue;
    }

    @chmod($destino, 0644);
    $escritos[] = [$ruta, strlen($datos)];
}
?>
<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Desempaquetar Human Coins</title>
<meta name="robots" content="noindex, nofollow">
<link rel="stylesheet" href="estilo.css">
</head>
<body>

<div class="page">

  <div class="intro">
    <h1 class="serif"><?= $errores ? 'Quedo a medias.' : 'Archivos desempaquetados.' ?></h1>
    <p><?= count($escritos) ?> de <?= count($ARCHIVOS) ?> archivos escritos en el servidor.</p>
  </div>

  <?php if ($errores): ?>
    <section class="block">
      <h2>Lo que fallo</h2>
      <?php foreach ($errores as $e): ?>
        <div class="error-text"><?= htmlspecialchars($e, ENT_QUOTES, 'UTF-8') ?></div>
      <?php endforeach; ?>
      <p class="hint">Casi siempre es permiso de escritura en la carpeta. Ponla en 755 y recarga esta pagina.</p>
    </section>
  <?php endif; ?>

  <section class="block">
    <h2>Archivos escritos</h2>
    <ul class="pairs">
      <?php foreach ($escritos as $e): ?>
        <li><span><?= htmlspecialchars($e[0], ENT_QUOTES, 'UTF-8') ?></span><strong><?= number_format($e[1] / 1024, 1, ',', '.') ?> KB</strong></li>
      <?php endforeach; ?>
    </ul>
  </section>

  <?php if (!$errores): ?>
    <section class="block">
      <h2>Sigue</h2>
      <p>Ahora abre el instalador para crear la base de datos y las tablas.</p>
    </section>
    <a class="primary-btn" href="instalar.php" style="display:block;text-align:center;text-decoration:none">Ir al instalador</a>
    <p class="hint">Cuando termines, borra este archivo y tambien instalar.php.</p>
  <?php endif; ?>

</div>

</body>
</html>
